import { cn } from '@cascivo/core/pure'
import { builtin, t } from '@cascivo/i18n'
import type { HTMLAttributes, ReactNode } from 'react'
import { Button } from '../button/button'
import { ShimmerText } from '../shimmer-text/shimmer-text'
import styles from './ai-status.module.css'

export type AiStatusValue = 'thinking' | 'generating' | 'complete' | 'error' | 'stopped'

export interface AiStatusProps extends HTMLAttributes<HTMLDivElement> {
  status: AiStatusValue
  label?: ReactNode
  labels?: {
    thinking?: string
    generating?: string
    complete?: string
    error?: string
    stopped?: string
    stop?: string
  }
  onStop?: () => void
}

function defaultLabel(status: AiStatusValue, labels: AiStatusProps['labels']): string {
  switch (status) {
    case 'thinking':
      return labels?.thinking ?? t(builtin.aiStatus.thinking)
    case 'generating':
      return labels?.generating ?? t(builtin.aiStatus.generating)
    case 'complete':
      return labels?.complete ?? t(builtin.aiStatus.complete)
    case 'error':
      return labels?.error ?? t(builtin.aiStatus.error)
    case 'stopped':
      return labels?.stopped ?? t(builtin.aiStatus.stopped)
  }
}

function StatusGlyph({ status }: { status: AiStatusValue }) {
  if (status === 'thinking' || status === 'generating') {
    return (
      <svg viewBox="0 0 16 16" width="16" height="16" fill="currentColor" aria-hidden="true">
        <path d="M8 1c.6 3.9 3.1 6.4 7 7-3.9.6-6.4 3.1-7 7-.6-3.9-3.1-6.4-7-7 3.9-.6 6.4-3.1 7-7Z" />
      </svg>
    )
  }
  if (status === 'complete') {
    return (
      <svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true">
        <path
          d="M3.5 8.5l3 3 6-7"
          stroke="currentColor"
          strokeWidth="1.75"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    )
  }
  if (status === 'error') {
    return (
      <svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true">
        <path
          d="M8 4.5v4M8 11h.01"
          stroke="currentColor"
          strokeWidth="1.75"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      </svg>
    )
  }
  return (
    <svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <rect x="5.5" y="5.5" width="5" height="5" rx="1" fill="currentColor" />
    </svg>
  )
}

export function AiStatus({ status, label, labels, onStop, className, ...props }: AiStatusProps) {
  const active = status === 'thinking' || status === 'generating'
  const text = label ?? defaultLabel(status, labels)

  return (
    <div
      data-status={status}
      className={cn(styles['ai-status'], className as string | undefined)}
      {...props}
    >
      <span className={styles['glyph']} aria-hidden="true">
        <StatusGlyph status={status} />
      </span>
      {/* The status node holds one stable string per phase, so a phase change is announced
          once; the Stop button sits outside it so pressing Stop does not re-announce. */}
      <span role="status" className={styles['label']}>
        {active ? <ShimmerText>{text}</ShimmerText> : text}
      </span>
      {active && onStop && (
        <Button variant="ghost" size="sm" className={styles['stop']} onClick={onStop}>
          {labels?.stop ?? t(builtin.aiStatus.stop)}
        </Button>
      )}
    </div>
  )
}

@layer cascivo.component {
  .ai-status {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--cascivo-space-2);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-none);
    color: var(--cascivo-color-text);

    &[data-status='complete'] {
      color: var(--cascivo-color-success-foreground, var(--cascivo-color-success));
    }

    &[data-status='error'] {
      color: var(--cascivo-color-destructive);
    }

    &[data-status='stopped'] {
      color: var(--cascivo-color-text-muted);
    }
  }

  .glyph {
    display: inline-flex;
    flex-shrink: 0;
    inline-size: 1rem;
    block-size: 1rem;

    & svg {
      inline-size: 100%;
      block-size: 100%;
    }

    [data-status='thinking'] > &,
    [data-status='generating'] > & {
      color: var(--cascivo-color-ai);
    }
  }

  .label {
    color: inherit;
  }

  .stop {
    margin-inline-start: var(--cascivo-space-1);
  }

  /* Decorative loop on the glyph only — never on the label, whose contrast must hold. */
  @media (prefers-reduced-motion: no-preference) {
    [data-status='thinking'] > .glyph,
    [data-status='generating'] > .glyph {
      animation: global(cascivo-pulse) var(--cascivo-duration-loop-slow) var(--cascivo-ease-in-out)
        infinite;
    }
  }
}

@media (forced-colors: active) {
  .ai-status,
  .ai-status .glyph {
    color: CanvasText;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'AiStatus',
  description:
    'Announces what an AI is doing — thinking, generating, done, failed or stopped — with a shimmering label and an optional Stop button',
  category: 'feedback',
  // The status renders and is announced from server HTML; only the Stop button needs JS.
  clientJs: 'enhancement',
  states: ['thinking', 'generating', 'complete', 'error', 'stopped'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'status',
      description:
        'The phase: `thinking` (working, nothing produced yet), `generating` (output is streaming), `complete`, `error`, or `stopped` (the reader pressed Stop).',
      type: "'thinking' | 'generating' | 'complete' | 'error' | 'stopped'",
      required: true,
    },
    {
      name: 'label',
      nameVisibility: 'visible',
      description:
        'Replaces the default text for the current status, e.g. "Searching 12 documents…".',
      type: 'ReactNode',
      required: false,
    },
    {
      name: 'labels',
      description: 'Overrides for the component’s user-visible strings (i18n).',
      type: '{ thinking?: string; generating?: string; complete?: string; error?: string; stopped?: string; stop?: string }',
      required: false,
    },
    {
      name: 'onStop',
      description:
        'Called when the reader presses Stop. When set, a Stop button renders while the status is `thinking` or `generating`.',
      type: '() => void',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-ai',
    '--cascivo-color-text',
    '--cascivo-color-text-muted',
    '--cascivo-color-success',
    '--cascivo-color-destructive',
    '--cascivo-duration-loop-slow',
  ],
  accessibility: {
    role: 'status',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'Enter', 'Space'],
    reducedMotion: true,
    forcedColors: true,
  },
  examples: [
    { title: 'Thinking', code: '<AiStatus status="thinking" />' },
    {
      title: 'Generating, with Stop',
      code: '<AiStatus status="generating" onStop={() => {}} />',
    },
    {
      title: 'Custom label',
      code: '<AiStatus status="thinking" label="Searching 12 documents…" />',
    },
    { title: 'Complete', code: '<AiStatus status="complete" />' },
    { title: 'Error', code: '<AiStatus status="error" />' },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  registryDependencies: ['button', 'shimmer-text'],
  tags: ['ai', 'status', 'loading', 'thinking', 'generating', 'progress', 'stop'],
  intent: {
    whenToUse: [
      'Telling the reader an AI request is in flight, and which phase it is in (thinking before output, generating while it streams)',
      'Offering a keyboard-reachable Stop while a response is being produced',
      'Reporting the terminal outcome of a generation — done, failed or stopped',
    ],
    whenNotToUse: [
      'Non-AI async work such as saving a form — use InlineLoading',
      'Holding the place of a chat reply with no text — use TypingIndicator',
      'Determinate progress with a known percentage — use ProgressBar',
    ],
    antiPatterns: [
      {
        bad: 'aria-live on the streaming response text',
        good: '<AiStatus status={phase} /> beside the response, which renders silently',
        why: 'A live region on streaming text re-announces on every token; AiStatus announces each phase change once',
      },
      {
        bad: 'Showing AiStatus for a response that arrives in under a second',
        good: 'Delay mounting it ~1s so fast responses never flash a loader',
        why: 'A loader that blinks on and off reads as a glitch and makes a screen reader announce noise',
      },
    ],
    related: [
      {
        name: 'ShimmerText',
        relationship: 'contains',
        reason: 'The in-progress label is rendered in ShimmerText',
      },
      {
        name: 'InlineLoading',
        relationship: 'alternative',
        reason: 'InlineLoading is the neutral, non-AI save/submit status',
      },
      {
        name: 'TypingIndicator',
        relationship: 'alternative',
        reason: 'TypingIndicator is the wordless placeholder inside a chat bubble',
      },
      {
        name: 'Reasoning',
        relationship: 'pairs-with',
        reason: 'Reasoning shows the model’s thinking while AiStatus reports the phase',
      },
    ],
    a11yRationale:
      'The label lives in a role="status" node holding one stable string per phase, so each phase change is announced once and token-level streaming never is. The glyph is aria-hidden and only it pulses (under prefers-reduced-motion: no-preference), so the label never drops below contrast. Stop is a real button outside the status node, so pressing it does not re-announce; forced colours render everything CanvasText',
    content: {
      tone: 'Present progressive while working ("Thinking…", "Searching the docs…"), terse when done ("Done", "Stopped")',
      notes: 'Name the specific work when you can; keep it to one line',
    },
    flexibility: [
      {
        area: 'label',
        level: 'flexible',
        note: 'Defaults per status come from the i18n catalog; override with label or the labels map',
      },
      {
        area: 'status semantics',
        level: 'strict',
        note: 'thinking/generating are in progress (sparkle + shimmer); complete/error/stopped are terminal — do not repurpose',
      },
    ],
  },
}
